function eventTable(events){return `<div class="table-wrap"><table class="data-table"><thead><tr><th>UTC TIME</th><th>SOURCE</th><th>ENTITY</th><th>RAW DETAIL / FIELDS</th></tr></thead><tbody>${events.map(e=>`<tr><td>${safe(e.time)}</td><td>${safe(e.source)}</td><td>${safe(e.asset)}</td><td class="truncate">${safe(e.detail)}</td></tr>`).join('')}</tbody></table></div>`;}
function consoleView(){const result=state.consoleResult;
 return `${pageIntro('03 / QUERY WORKBENCH','Make the logs talk',`Search synthetic endpoint, identity, network, mail and cloud records from ${DATA.cases.length} cases. This is a deliberately small training query language—not full SPL or KQL. Learn query thinking here, then study authentic SPL and KQL examples below.`)}
 <div class="grid g2"><section class="panel"><div class="panel-title">QUERY EDITOR <span class="mono">LOCAL / NO BACKEND</span></div><textarea id="console-query" spellcheck="false" class="console-editor" aria-label="Simulated log query">${safe(state.consoleQuery)}</textarea><div class="console-toolbar"><span class="console-info">${LOGS.length} synthetic records indexed</span>${btn('▶ Run query','run-query',{small:true})}</div></section><section class="panel"><div class="panel-title">LANGUAGE REFERENCE <span class="mono">FIELDWORK DSL</span></div><div class="panel-pad"><p class="mono font-small">Fields: <span class="text-accent">time, source, asset, detail, tier, case</span></p><p class="mono font-small"><span class="text-accent">=</span> exact match &nbsp; <span class="text-accent">~</span> contains text</p><p class="mono font-small">Connect filters with <span class="text-accent">AND</span> or <span class="text-accent">OR</span></p><p class="mono font-small">Pipes: <span class="text-accent">count by</span>, <span class="text-accent">sort</span>, <span class="text-accent">limit</span></p><p class="tip">Examples are sandboxed string filters, not expressions executed on your device.</p></div></section></div>
 <div class="query-samples">${['source=edr','source=idp AND detail~FAIL','asset~WKSTN','detail~4624','source=sysmon | count by asset','tier=L2 | sort time desc | limit 20'].map(s=>`<button class="chip-btn" data-action="query-example" data-query="${safe(s)}">${safe(s)}</button>`).join('')}</div>
 <section class="panel"><div class="panel-title">RESULT STREAM <span class="mono">${state.consoleError?'QUERY ERROR':result?`${result.matched} ROWS`:'NOT EXECUTED'}</span></div>${state.consoleError?`<div class="feedback bad" style="margin:18px">${safe(state.consoleError)}</div>`:result?(result.rows.length?`<div class="table-wrap"><table class="data-table"><thead><tr>${result.columns.map(k=>`<th>${safe(k)}</th>`).join('')}</tr></thead><tbody>${result.rows.map(r=>`<tr>${result.columns.map(k=>`<td>${safe(r[k])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:'<div class="empty-state"><span>∅</span>No matching records. Check fields, spelling or time/asset scope.</div>'):'<div class="empty-state"><span>&gt;_</span>Enter a query and choose Run query to view results.</div>'}</section>
 ${sectionHead('Production query notebook','Reference patterns to adapt in Splunk and Microsoft Sentinel. These examples are not executed in the local simulator.')}
 <div class="grid g2">${DATA.queries.map((q,i)=>`<article class="panel"><div class="panel-title">${safe(q.title)} ${tag(q.language,q.language==='KQL'?'blue':'green')}</div><div class="code-box" style="margin:0;border:0;border-radius:0"><div class="code-head"><span>${q.language} / EXAMPLE ${formatCount(i+1)}</span><button class="chip-btn" data-action="copy-query" data-index="${i}">COPY</button></div><pre>${safe(q.code)}</pre></div><div class="panel-slim"><p style="margin:0;font-size:12px">${safe(q.meaning)}</p></div></article>`).join('')}</div>`;
}
function drillsView(){
 const d=DATA.drills.find(x=>x.id===state.drillId)||DATA.drills[0], done=Boolean(state.progress.drills[d.id]), attempts=state.drillAttempts[d.id]||0, fb=state.drillFeedback?.id===d.id?state.drillFeedback:null;
 const showAnswer=attempts>=2;
 return `${pageIntro('04 / EVIDENCE PRACTICE','Evidence retrieval drills','Solve investigation objectives with the sandbox query language. These are graded on exact matching event sets: overly broad or incomplete queries do not pass. Earn 50 XP per drill.')}
 <div class="grid drill-grid"><section class="panel"><div class="panel-title">QUERY OBJECTIVES <span class="mono">${completed('drills')}/${DATA.drills.length} CLEARED</span></div><div class="list-scroll">${DATA.drills.map(x=>`<button class="item-row ${d.id===x.id?'active':''}" data-action="open-drill" data-id="${x.id}"><span class="item-id">${safe(x.id.toUpperCase())}</span><span class="item-content"><strong>${safe(x.title)}</strong><small>${safe(x.tier)} · EVIDENCE TARGET</small></span><span class="item-check ${state.progress.drills[x.id]?'done':''}">${state.progress.drills[x.id]?'✓':'○'}</span></button>`).join('')}</div></section>
 <section class="panel"><div class="detail-header">${tierTag(d.tier)} ${tag(d.id.toUpperCase())} <h2 style="margin:14px 0 6px">${safe(d.title)}</h2><p class="lead">${safe(d.task)}</p></div><div class="detail-content"><div class="eyebrow">WORKBENCH / EXACT MATCH</div><p>Use <code>case=s01 AND source=idp</code>, <code>detail~FAIL</code>, <code>OR</code>, and optionally <code>| sort time asc</code>. This drill requires event rows (not <code>count by</code>).</p><textarea class="console-editor drill-editor" id="drill-query" spellcheck="false" aria-label="Drill log query" placeholder="case=s01 AND source=idp">${safe(state.drillQuery)}</textarea><div class="action-row">${btn(done?'✓ Drill cleared':'Grade query','grade-drill',{extra:done?'disabled':''})}${btn(state.drillHint?'Hint visible':'Show hint','drill-hint',{variant:'secondary'})}${btn('Browse all logs →','nav',{variant:'ghost',extra:'data-route="console"'})}</div>
 ${state.drillHint?`<div class="note-box"><h4>INVESTIGATION HINT</h4><p>${safe(d.hint)}</p></div>`:''}
 ${fb?`<div class="feedback ${fb.passed?'':'bad'}" role="status"><b>${fb.passed?'✓ Correct query':'Not quite yet'}</b> · ${fb.matched} matching events · ${fb.target} expected · ${fb.missing} missing · ${fb.extra} extra. ${fb.passed?safe(d.lesson):'Tighten the filter or include missing evidence. Run the query again to try another hypothesis.'}</div>`:''}
 ${showAnswer&&!done?`<div class="note-box warn"><h4>REFERENCE FILTER (AFTER TWO ATTEMPTS)</h4><code>${safe(d.solution)}</code><p>Use this as a learning reference; submitting the correct evidence set is still required.</p></div>`:''}
 ${done?`<div class="note-box"><h4>TAKEAWAY</h4><p>${safe(d.lesson)}</p></div>`:''}
 <p class="footnote">The fieldwork query language is not SPL/KQL. Only local fictional log records are used. Grading compares complete event IDs from the stored answer set; sorting is allowed.</p></div></section></div>`;
}
function gradeDrill(){const d=DATA.drills.find(x=>x.id===state.drillId);if(!d)return;
 state.drillAttempts[d.id]=(state.drillAttempts[d.id]||0)+1;
 try{const actual=runSimQuery(state.drillQuery),expected=runSimQuery(d.solution),want=new Set(expected.rows.map(x=>x.event));
 if(actual.rows.some(x=>!x.event))throw new Error('Drills require raw matching events; remove aggregate operators like count by.');
 const got=new Set(actual.rows.map(x=>x.event)),missing=[...want].filter(x=>!got.has(x)).length,extra=[...got].filter(x=>!want.has(x)).length;
 const passed=want.size>0&&missing===0&&extra===0;
 state.drillFeedback={id:d.id,passed,matched:got.size,target:want.size,missing,extra};
 if(passed)setDone('drills',d.id);
 }catch(e){state.drillFeedback={id:d.id,passed:false,matched:0,target:'—',missing:'—',extra:'—'};toast('Query error: '+e.message);}
 render();
}
function pickQuiz(tier,exclude=null){const pool=DATA.questions.filter(x=>(tier==='All'||x.tier===tier)&&x.id!==exclude);if(!pool.length)return DATA.questions[0];const unmastered=pool.filter(x=>!state.progress.quiz[x.id]);const candidates=unmastered.length?unmastered:pool;return candidates[Math.floor(Math.random()*candidates.length)];}
function quizView(){const q=DATA.questions.find(x=>x.id===state.quizId)||DATA.questions[0];const options=shuffledOptions(q.id,q.options);const chosen=state.quizAnswer,checked=state.quizFeedback;
 return `${pageIntro('05 / KNOWLEDGE EXAM','Prove what you know',`${DATA.questions.length} knowledge-check questions across foundations and three analyst tiers. Answers are shuffled, explained, and tracked locally. Incorrect answers can be retried later.`)}
 <div class="toolbar"><div class="segment">${['All','Foundation','L1','L2','L3'].map(t=>`<button data-action="quiz-level" data-level="${t}" class="${state.quizLevel===t?'active':''}">${t}</button>`).join('')}</div>${tag(completed('quiz')+'/'+DATA.questions.length+' mastered','green')}</div>
 <div class="panel" style="max-width:880px"><div class="detail-header"><div class="flex space-between">${tierTag(q.tier)}<span class="kicker">QUESTION ${safe(q.id.slice(1))} / ${DATA.questions.length}</span></div><h2 style="margin:19px 0 2px">${safe(q.question)}</h2></div><div class="detail-content"><div class="answer-list">${options.map((o,i)=>`<button class="answer-option ${chosen===o.index?(checked?(o.index===q.answer?'correct':'incorrect'):'selected'):''} ${checked&&o.index===q.answer?'correct':''}" data-action="quiz-answer" data-choice="${o.index}" ${checked?'disabled':''}><span class="answer-letter">${String.fromCharCode(65+i)}</span>${safe(o.text)}</button>`).join('')}</div>${checked?`<div class="feedback ${chosen===q.answer?'':'bad'}">${chosen===q.answer?'Correct — +10 XP on first mastery.':'Not this time.'} ${safe(q.why)}</div>`:''}<div class="action-row">${btn('Check answer','submit-quiz',{extra:checked||chosen===null?'disabled':''})}${btn('Next question →','next-quiz',{variant:'secondary'})}</div></div></div>
 <div class="note-box" style="max-width:880px"><h4>EXAM STRATEGY</h4><p>Answer in the order an analyst works: what the evidence proves, what remains unknown, which log would reduce uncertainty, and what should be escalated. Avoid overconfident claims.</p></div>`;
}
