function nav(route){if(!ROUTES.includes(route))return;state.route=route;state.mobileOpen=false;history.replaceState(null,'','#'+route);render();window.scrollTo({top:0,behavior:'instant'});}
function consoleSubmit(){try{state.consoleResult=runSimQuery(state.consoleQuery);state.consoleError=null;}catch(e){state.consoleError=e.message;state.consoleResult=null;}render();}
function resetProgress(){if(!window.confirm('Clear ALL lessons, cases, evidence drills, quizzes, interviews and shift checks stored in this browser? Export a backup first.'))return;state.progress=INITIAL_PROGRESS();save();render();toast('Progress reset on this device.');}
function exportProgress(){const payload=JSON.stringify({kind:'soc-fieldwork-profile',exportedAt:new Date().toISOString(),progress:state.progress},null,2),blob=new Blob([payload],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='soc-fieldwork-progress.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function validateImportedProgress(obj){const p=obj?.kind==='soc-fieldwork-profile'?obj.progress:obj;if(!p||p.version!==1||!['lessons','cases','quiz','interviews','shift'].every(k=>p[k]&&typeof p[k]==='object'&&!Array.isArray(p[k])))throw new Error('This is not a recognized fieldwork progress file.');for(const bucket of ['lessons','cases','quiz','interviews','drills']){if(bucket==='drills'&&!p.drills)continue;const validKeys=new Set((bucket==='lessons'?DATA.lessons:bucket==='cases'?DATA.cases:bucket==='quiz'?DATA.questions:bucket==='drills'?DATA.drills:DATA.interviews).map(x=>x.id));for(const [id,value] of Object.entries(p[bucket])){if(!validKeys.has(id)||typeof value!=='boolean'&&typeof value!=='number')throw new Error('Progress entries are not valid.');}}return {...p,notes:p.notes&&typeof p.notes==='object'&&!Array.isArray(p.notes)?p.notes:{},drills:p.drills&&typeof p.drills==='object'&&!Array.isArray(p.drills)?p.drills:{}};}
function copyText(text){if(navigator.clipboard?.writeText){navigator.clipboard.writeText(text).then(()=>toast('Copied to clipboard.')).catch(()=>fallbackCopy(text));}else fallbackCopy(text);}
function fallbackCopy(text){const t=document.createElement('textarea');t.value=text;document.body.append(t);t.select();try{document.execCommand('copy');toast('Copied to clipboard.');}catch{toast('Clipboard not available in this browser.');}t.remove();}
function inputRerender(prop,id,value){const el=document.getElementById(id),cursor=el?.selectionStart;state[prop]=value;render();const fresh=document.getElementById(id);if(fresh){fresh.focus();try{fresh.setSelectionRange(cursor,cursor)}catch{}}}

document.addEventListener('click',event=>{const control=event.target.closest('[data-action]');if(!control)return;const action=control.dataset.action,id=control.dataset.id;
 switch(action){
 case 'nav':nav(control.dataset.route);break;
 case 'atlas-filter':state.atlasCategory=control.dataset.category;render();break;
 case 'atlas-item':state.atlasIndex=Number(control.dataset.index);render();break;
 case 'timeline-case':state.timelineCase=id;state.timelineSource='All';render();break;
 case 'timeline-source':state.timelineSource=control.dataset.source;render();break;
 case 'timeline-investigate':state.caseId=id;state.caseFeedback=null;nav('missions');break;
 case 'mobile':state.mobileOpen=!state.mobileOpen;render();break;
 case 'open-tier':state.level=control.dataset.tier;state.lessonSearch='';state.lessonId=(DATA.lessons.find(x=>x.tier===state.level)||DATA.lessons[0]).id;state.lessonAnswer=null;nav('academy');break;
 case 'level':state.level=control.dataset.level;render();break;
 case 'open-lesson':state.lessonId=id;state.lessonAnswer=null;render();break;
 case 'lesson-answer':state.lessonAnswer={id,choice:Number(control.dataset.choice)};render();break;
 case 'complete-lesson':setDone('lessons',id);render();break;
 case 'open-case':state.caseId=id;state.caseFeedback=null;nav('missions');break;
 case 'case-answer':{const c=control.dataset.case,qi=Number(control.dataset.question);state.caseAnswers[c]??={};state.caseAnswers[c][qi]=Number(control.dataset.choice);state.caseFeedback=null;render();break;}
 case 'reset-case':state.caseAnswers[id]={};state.caseFeedback=null;render();break;
 case 'submit-case':{const c=DATA.cases.find(x=>x.id===id),a=state.caseAnswers[id]||{};if(Object.keys(a).length<c.questions.length){toast('Make all three decisions first.');break;}const score=c.questions.filter((q,i)=>a[i]===q.answer).length,passed=score===c.questions.length;state.caseFeedback={id,score,passed};if(passed)setDone('cases',id);render();break;}
 case 'run-query':consoleSubmit();break;
 case 'open-drill':state.drillId=id;state.drillFeedback=null;state.drillHint=false;state.drillQuery='';render();break;
 case 'grade-drill':gradeDrill();break;
 case 'drill-hint':state.drillHint=!state.drillHint;render();break;
 case 'query-example':state.consoleQuery=control.dataset.query;consoleSubmit();break;
 case 'copy-query':copyText(DATA.queries[Number(control.dataset.index)].code);break;
 case 'copy-handoff':{const c=DATA.cases.find(x=>x.id===id);copyText(`CASE ${c.id.toUpperCase()}: ${c.name}\nTier: ${c.tier} | Asset: ${c.host} | Technique: ${c.attack}\nSummary: ${c.summary}\n\nAnalyst notes:\n${state.progress.notes[id]||'(not yet entered)'}\n\nEvidence: ${c.events.length} synthetic events reviewed`);break;}
 case 'quiz-level':state.quizLevel=control.dataset.level;state.quizId=pickQuiz(state.quizLevel,state.quizId).id;state.quizAnswer=null;state.quizFeedback=null;render();break;
 case 'quiz-answer':state.quizAnswer=Number(control.dataset.choice);render();break;
 case 'submit-quiz':{const q=DATA.questions.find(x=>x.id===state.quizId);if(state.quizAnswer===null)break;state.quizFeedback=true;if(q.answer===state.quizAnswer)setDone('quiz',q.id);render();break;}
 case 'next-quiz':state.quizId=pickQuiz(state.quizLevel,state.quizId).id;state.quizAnswer=null;state.quizFeedback=null;render();break;
 case 'interview-level':state.interviewLevel=control.dataset.level;state.interviewId=pickInterview(state.interviewLevel,state.interviewId).id;state.interviewReveal=false;render();break;
 case 'interview-reveal':state.interviewReveal=true;render();break;
 case 'interview-master':setDone('interviews',id);state.interviewId=pickInterview(state.interviewLevel,id).id;state.interviewReveal=false;render();break;
 case 'next-interview':state.interviewId=pickInterview(state.interviewLevel,state.interviewId).id;state.interviewReveal=false;render();break;
 case 'open-runbook':state.runbookId=id;render();break;
 case 'copy-runbook':{const r=DATA.runbooks.find(x=>x.id===id);copyText(r.title+'\n'+r.steps.map((s,i)=>`${i+1}. ${s}`).join('\n'));break;}
 case 'export-progress':exportProgress();break;
 case 'reset-progress':resetProgress();break;
 }
});
document.addEventListener('input',event=>{const id=event.target.id;if(id==='atlas-search')inputRerender('atlasSearch',id,event.target.value);else if(id==='lesson-search')inputRerender('lessonSearch',id,event.target.value);else if(id==='case-search')inputRerender('caseSearch',id,event.target.value);else if(id==='glossary-search')inputRerender('glossarySearch',id,event.target.value);else if(id==='console-query')state.consoleQuery=event.target.value;else if(id==='drill-query')state.drillQuery=event.target.value;else if(id==='case-notes'){state.progress.notes[state.caseId]=event.target.value;save();}});
document.addEventListener('change',event=>{if(event.target.hasAttribute('data-shift-index')){const key=shiftKey();state.progress.shift[key]??={};state.progress.shift[key][Number(event.target.dataset.shiftIndex)]=event.target.checked;save();render();}else if(event.target.id==='progress-import'){const file=event.target.files?.[0];if(!file)return;if(file.size>1000000){toast('Progress file must be under 1 MB.');return;}file.text().then(s=>{state.progress=validateImportedProgress(JSON.parse(s));save();render();toast('Progress imported successfully.');}).catch(e=>toast(`Could not import: ${e.message}`));}});
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(ROUTES.includes(next)&&next!==state.route){state.route=next;render();}});
render();
